/// FUNCTION: Whether the help documents a variable of this full
/// spelling, as `b:changedtick`.
pub fn has(name: &str) -> bool {
    NAMES.binary_search(&name).is_ok()
}

#[cfg(test)]
mod tests {
    use super::has;
    use super::NAMES;

    /// The lookup is a binary search, which answers an unordered table
    /// wrongly rather than slowly.
    #[test]
    fn the_table_is_ordered_and_each_name_appears_once() {
        assert!(NAMES.windows(2).all(|pair| pair[0] < pair[1]));
    }

    #[test]
    fn a_variable_vim_documents_is_in_the_table() {
        for name in ["g:colors_name", "b:changedtick", "b:current_syntax"] {
            assert!(has(name), "{name} is a variable Vim documents");
        }
    }

    #[test]
    fn a_variable_a_project_could_declare_is_not_in_the_table() {
        assert!(!has("g:bartleby_binder_root"));
    }
}
